/// One explicit (forward) **Euler** step of `dy/dt = f(t, y)`:
/// `y_{n+1} = y_n + h f(t_n, y_n)`.
///
/// The simplest ODE integrator: first-order accurate (global error `O(h)`) and
/// only conditionally stable, so it needs small steps for stiff problems.
///
/// Generated by kovan-codegen (docs/kovan.md § "Numerical Methods → ODE
/// Solvers"). Deterministic template; depends only on `core`/`std` `f64`.
pub fn euler_step<F>(f: &F, t: f64, y: f64, h: f64) -> f64
where
    F: Fn(f64, f64) -> f64,
{
    y + h * f(t, y)
}

/// Integrate `dy/dt = f(t, y)` from `(t0, y0)` for `n` steps of size `h` with
/// explicit Euler, returning the `(t, y)` trajectory (length `n + 1`, including
/// the initial point).
pub fn euler_integrate<F>(f: F, t0: f64, y0: f64, h: f64, n: usize) -> Vec<(f64, f64)>
where
    F: Fn(f64, f64) -> f64,
{
    let mut out = Vec::with_capacity(n + 1);
    let mut t = t0;
    let mut y = y0;
    out.push((t, y));
    for _ in 0..n {
        y = euler_step(&f, t, y, h);
        t += h;
        out.push((t, y));
    }
    out
}
